<div class="page-title"><div><em>HELP CENTER</em><h1><?=tl('support_title')?></h1><p><?=tl('support_sub')?></p></div><button class="btn" data-modal="ticket-modal"><?=tl('start_conversation')?></button></div><div class="support-search">⌕ <input id="help-search" placeholder="Search for help with payments, cards, accounts..."></div><div class="help-grid" id="help-grid"><article data-help="cards freeze lost limits"><i>▤</i><h3>Cards</h3><p>Freeze a card, report it lost, or manage limits.</p></article><article data-help="payments transfer recipients status"><i>↗</i><h3>Payments</h3><p>Transfer status, recipients and payment help.</p></article><article data-help="security password verification account safe"><i>✓</i><h3>Security</h3><p>Password, verification and account safety.</p></article><article data-help="accounts statements details access"><i>▥</i><h3>Accounts</h3><p>Statements, details and account access.</p></article></div>
<script>var hs=document.getElementById('help-search');if(hs){hs.addEventListener('input',function(){var q=hs.value.trim().toLowerCase();document.querySelectorAll('[data-help]').forEach(function(a){a.style.display=(!q||a.getAttribute('data-help').indexOf(q)>-1)?'':'none';});});}</script><h2 class="section-title"><?=tl('your_requests')?></h2><?php if(!$tickets):?><div class="empty">You have no support requests yet. Start a conversation to get help.</div><?php else:?><section class="panel list"><?php foreach($tickets as $t):?><a class="list-row" href="<?=site_url('support/'.$t['id'])?>"><span class="avatar">?</span><div><b><?=html_escape($t['subject'])?></b><small><?=$t['reference']?> · <?=date('M j, g:i a',strtotime($t['updated_at']))?></small></div><span class="<?=status_class($t['status'])?>"><?=ucwords(str_replace('_',' ',$t['status']))?></span><b class="row-arrow">›</b></a><?php endforeach?></section><?php endif?><dialog id="ticket-modal"><div class="dialog-head"><h2>Contact support</h2><button data-close>×</button></div><?=form_open('support/create')?><label>Category</label><select name="category"><option>General</option><option>Cards</option><option>Transfers</option><option>Security</option></select><label>Subject</label><input name="subject" required><label>Message</label><textarea name="message" required rows="6"></textarea><button class="btn wide">Submit request</button></form></dialog>
